114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
120	        owner.setTelephone(normalizedTelephone);
121	        owner.setEmail(normalizeEmail(owner.getEmail()));
122	        owner.setAddress(normalizeAddress(owner.getAddress()));
123	        validatePostcode(owner.getCity(), owner.getPostcode());
124	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
125	        if (effectiveRegistrationDate == null) {
126	            effectiveRegistrationDate = LocalDate.now();
127	        } else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
128	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
129	                "registrationDate must not be later than the current server date");
130	        }
131	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
132	        owner.setRegistrationDate(effectiveRegistrationDate);
133	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
134	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
135	                "the maximum number of owners that may be created today has been reached");
136	        }
137	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
138	        // The household id is deterministic (derived from the last name and postcode), so every
139	        // owner is keyed to its household automatically, regardless of creation order.
140	        this.clinicService.assignHousehold(owner);
141	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner.getHouseholdId(), null);
142	        if (householdInUse && !sharesHousehold) {
143	            throw new ResponseStatusException(HttpStatus.CONFLICT,
144	                "an owner in the same household already exists");
145	        }
146	        if (isIdentityKeyInUse(ownerMapper.toIdentityKey(owner), null)) {
147	            throw new ResponseStatusException(HttpStatus.CONFLICT,
148	                "an owner with the same identity already exists");
149	        }
150	        if (countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
151	            throw new ResponseStatusException(HttpStatus.CONFLICT,
152	                "city has reached its maximum number of owners");
153	        }
154	        owner.setCustomerCode(customerCodeFor(owner));
155	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
156	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
157	        owner.setBulkSignupWarning(
158	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
159	        // A declared household member (one created with 'sharesHousehold' that joins an existing
160	        // household) is not a suspected duplicate, so it is never flagged as a possible duplicate.
161	        boolean declaredHouseholdMember = sharesHousehold && householdInUse;
162	        Owner softDuplicate = declaredHouseholdMember ? null : findPossibleDuplicate(owner);
163	        owner.setPossibleDuplicate(softDuplicate != null);
164	        owner.setPossibleDuplicateOf(softDuplicate == null ? null : softDuplicate.getId());
165	        this.clinicService.saveOwner(owner);
166	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
167	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
168	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
169	            ownerDto.getMembershipLevel());
170	        headers.setLocation(UriComponentsBuilder.newInstance()
171	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
172	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
173	    }
