269	    /**
270	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where REGION is
271	     * the region derived from the owner's postcode (preferring the postcode, falling back to the
272	     * city table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)}) and HASH8 is the
273	     * first 8 upper-case hex characters of the SHA-256 digest of the owner's normalized E.164
274	     * telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no
275	     * sequence number, so it is a stable function of the owner's region and telephone/last-name
276	     * identity rather than of creation order.
277	     *
278	     * @param owner the owner being created, with its telephone already normalized to E.164 form
279	     * @return the assigned customer code
280	     */
281	    private String customerCodeFor(Owner owner) {
282	        String region = ownerMapper.regionOf(owner);
283	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName()).substring(0, 8);
284	        return region + "-" + hash8;
285	    }
286	
287	    /**
288	     * Computes the SHA-256 digest of the UTF-8 bytes of {@code value} and renders it as an
289	     * upper-case hex string.
290	     *
291	     * @param value the string to hash
292	     * @return the full SHA-256 digest as upper-case hex
293	     */
294	    private static String sha256UpperHex(String value) {
295	        try {
296	            byte[] digest = MessageDigest.getInstance("SHA-256")
297	                .digest(value.getBytes(StandardCharsets.UTF_8));
298	            StringBuilder sb = new StringBuilder(digest.length * 2);
299	            for (byte b : digest) {
300	                sb.append(String.format("%02X", b));
301	            }
302	            return sb.toString();
303	        } catch (NoSuchAlgorithmException ex) {
304	            throw new IllegalStateException("SHA-256 not available", ex);
305	        }
306	    }
