308	    /**
309	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
310	     * owner's city already contains this many owners.
311	     */
312	    private static final int CITY_CAPACITY = 50;
313	
314	    /**
315	     * The maximum number of owners that may be created on a single day. A create is rejected with
316	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
317	     * {@code registrationDate}.
318	     */
319	    private static final int DAILY_CREATE_LIMIT = 100;
320	
321	    /**
322	     * The number of owners that must already have been created for the current day before a new
323	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
324	     * owners already carry today's {@code registrationDate}.
325	     */
326	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
327	
328	    /**
329	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday or
330	     * Sunday is moved forward to the following Monday, while a date already on a weekday is returned
331	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
332	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
333	     * falls on a business day.
334	     *
335	     * @param date the effective registration date
336	     * @return the same date when it is a weekday, otherwise the following Monday
337	     */
338	    private static LocalDate rollToBusinessDay(LocalDate date) {
339	        return switch (date.getDayOfWeek()) {
340	            case SATURDAY -> date.plusDays(2);
341	            case SUNDAY -> date.plusDays(1);
342	            default -> date;
343	        };
344	    }
