346	    /**
347	     * Counts the existing owners whose {@code registrationDate} equals the given (already
348	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
349	     * business day. Called before a new owner is saved, so the returned value reflects the number of
350	     * owners created for that day prior to this create.
351	     *
352	     * @param date the adjusted business-day registration date to count against
353	     * @return the number of existing owners registered on that date
354	     */
355	    private int countOwnersRegisteredOn(LocalDate date) {
356	        return (int) this.clinicService.findAllOwners().stream()
357	            .filter(existing -> date.equals(existing.getRegistrationDate()))
358	            .count();
359	    }
