387	     * Counts the existing owners that already share the given first name and last name, comparing
388	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
389	     * the number of namesakes that existed prior to this create.
390	     *
391	     * @param firstName the new owner's first name
392	     * @param lastName  the new owner's last name
393	     * @return the number of existing owners with the same first and last name
394	     */
395	    private int countNamesakes(String firstName, String lastName) {
396	        int count = 0;
397	        for (Owner existing : this.clinicService.findAllOwners()) {
398	            if (firstName.equalsIgnoreCase(existing.getFirstName())
399	                && lastName.equalsIgnoreCase(existing.getLastName())) {
400	                count++;
401	            }
402	        }
403	        return count;
404	    }
