406	    /**
407	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
408	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
409	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
410	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
411	     * string is what gets stored and returned.
412	     *
413	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
414	     *
415	     * <p>Once in E.164 form the national-number length is validated against the country code: a
416	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
417	     * number exactly 10 (see {@link E164PhoneNumbers#NATIONAL_LENGTHS}). Country codes without a configured
418	     * rule are accepted on the general 8-to-15 digit length alone.
419	     *
420	     * @param telephone the raw telephone value supplied by the client
421	     * @return the normalized E.164 telephone number
422	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
423	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
424	     *                                 after the {@code '+'}, or the wrong national-number length for
425	     *                                 its country code)
426	     */
427	    private static String normalizeTelephone(String telephone) {
428	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
429	        String digits;
430	        if (cleaned.startsWith("+")) {
431	            digits = cleaned.substring(1);
432	        } else {
433	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
434	            digits = "61" + national;
435	        }
436	        if (!digits.matches("[0-9]{8,15}")) {
437	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
438	                "telephone could not be normalized to a valid E.164 number");
439	        }
440	        validateNationalNumberLength(digits);
441	        return "+" + digits;
442	    }
443	
444	    /**
445	     * Validates the national-number length of an E.164 number (its digits, without the leading
446	     * {@code '+'}) against its country code. The longest dialling code that prefixes the number (see
447	     * {@link E164PhoneNumbers#countryCode}) selects the rule; if none is configured the number passes
448	     * (only the general 8-to-15 digit rule applies).
449	     *
450	     * @param digits the E.164 digits without the leading {@code '+'}
451	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
452	     *                                 digits does not match the country code's required length
453	     */
454	    private static void validateNationalNumberLength(String digits) {
455	        E164PhoneNumbers.countryCode(digits)
456	            .ifPresent(code -> {
457	                int nationalLength = digits.length() - code.length();
458	                int required = E164PhoneNumbers.NATIONAL_LENGTHS.get(code);
459	                if (nationalLength != required) {
460	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
461	                        "telephone must have " + required
462	                            + " national digits for country code +" + code);
463	                }
464	            });
465	    }
