467	    /**
468	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
469	     * containing at least one dot, none of the three sections containing whitespace or an
470	     * additional {@code @}.
471	     */
472	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
473	
474	    /**
475	     * Disposable email domains that are not accepted for an owner. An email whose domain is on this
476	     * blocklist is rejected with {@link HttpStatus#BAD_REQUEST}. Entries are lower-case and matched
477	     * case-insensitively against the domain (the part after the {@code @}).
478	     */
479	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
480	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
481	
482	    /**
483	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
484	     * (email is optional). When a value is supplied it must be a syntactically valid address whose
485	     * domain is not on the disposable-domain blocklist; the value is then stored and returned
486	     * lower-cased.
487	     *
488	     * @param email the raw email value supplied by the client, possibly {@code null}
489	     * @return the lower-cased email, or {@code null} when none was supplied
490	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
491	     *                                 is not a syntactically valid address, or its domain is on the
492	     *                                 disposable-domain blocklist
493	     */
494	    private static String normalizeEmail(String email) {
495	        if (email == null) {
496	            return null;
497	        }
498	        if (!EMAIL_PATTERN.matcher(email).matches()) {
499	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
500	                "email must be a syntactically valid address");
501	        }
502	        String normalized = email.toLowerCase(Locale.ROOT);
503	        String domain = normalized.substring(normalized.indexOf('@') + 1);
504	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
505	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
506	                "email domain " + domain + " is not allowed");
507	        }
508	        return normalized;
509	    }
