511	    /**
512	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
513	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
514	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
515	     */
516	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
517	        "NSW", new int[] {2000, 2099},
518	        "VIC", new int[] {3000, 3099},
519	        "QLD", new int[] {4000, 4099});
520	
521	    /**
522	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
523	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
524	     * four-digit format is enforced by request validation; here the value is range-checked: when the
525	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
526	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
527	     * accepts any four-digit postcode.
528	     *
529	     * @param city     the owner's city
530	     * @param postcode the owner's postcode, possibly {@code null}
531	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
532	     *                                 out of range for the city's region
533	     */
534	    private static void validatePostcode(String city, String postcode) {
535	        if (postcode == null) {
536	            return;
537	        }
538	        String region = OwnerMapper.CITY_REGION.get(city);
539	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
540	        if (range == null) {
541	            return;
542	        }
543	        int value = Integer.parseInt(postcode);
544	        if (value < range[0] || value > range[1]) {
545	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
546	                "postcode " + postcode + " is not valid for region " + region);
547	        }
548	    }
