550	    /**
551	     * Common street-type abbreviations expanded to their full word during address normalization.
552	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
553	     */
554	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
555	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
556	
557	    /**
558	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
559	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
560	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
561	     * {@code AVE -> AVENUE}). This normalized value is what gets stored and returned.
562	     *
563	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
564	     *
565	     * @param address the raw address supplied by the client, possibly {@code null}
566	     * @return the normalized address
567	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
568	     *                                 after normalization (required field)
569	     */
570	    private static String normalizeAddress(String address) {
571	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
572	        if (collapsed.isEmpty()) {
573	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
574	                "address must not be blank");
575	        }
576	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
577	        StringBuilder normalized = new StringBuilder();
578	        for (int i = 0; i < tokens.length; i++) {
579	            if (i > 0) {
580	                normalized.append(' ');
581	            }
582	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
583	        }
584	        return normalized.toString();
585	    }
