587	    /**
588	     * Determines whether the given whole identity key already belongs to any owner other than the
589	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
590	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
591	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
592	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
593	     *
594	     * @param identityKey the identity key to look for
595	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
596	     * @return {@code true} if another owner already has the same identity key
597	     */
598	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
599	        for (Owner existing : this.clinicService.findAllOwners()) {
600	            if (excludeId != null && excludeId.equals(existing.getId())) {
601	                continue;
602	            }
603	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
604	                return true;
605	            }
606	        }
607	        return false;
608	    }
