610	    /**
611	     * Finds the existing owner that the given (not-a-hard-duplicate) new owner is a possible
612	     * (soft) duplicate of: one that shares the new owner's last name (compared case-insensitively)
613	     * and postcode while carrying a <em>different</em> normalized telephone. A hard duplicate
614	     * (identical identity key) has already been rejected with a 409 before this runs, so this
615	     * flags only the softer last-name/postcode overlap. The match with the lowest id is returned
616	     * so the result is deterministic when several owners qualify.
617	     *
618	     * @param owner the new owner being created, with its telephone already normalized
619	     * @return the matching existing owner, or {@code null} when none qualifies
620	     */
621	    private Owner findPossibleDuplicate(Owner owner) {
622	        if (owner.getLastName() == null || owner.getPostcode() == null) {
623	            return null;
624	        }
625	        return this.clinicService.findAllOwners().stream()
626	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
627	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
628	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
629	            .min(Comparator.comparingInt(Owner::getId))
630	            .orElse(null);
631	    }
632	
633	}
